try:
 (root/'allow-skip').write_text('actual author admission');v=finish(root,proc,writer,1);assert v['attempts'][0]['status']=='failed'and not v['attempts'][0]['expected']and not v['attachments']and any('rollback failed'in e for e in v['globalErrors'])and len(files(root))==1
finally:directory.chmod(0o700)
root,proc,writer,parts=start('real-owner-exit-zero-after-native-accepted-cause-is-failure',"export default defineNativeSuite({tests:[{title:'actual accepted skip without raw settlement',expectedFailure:true,run:async(_,i)=>{void i.attach('held',{body:'actual held bytes'});await ready();try{i.skip('actual accepted cause')}catch{}while(i.expectedStatus!=='skipped')await wait(1);writeFileSync(process.env.ACTUAL_ACCEPTED_SKIP,String(process.pid));process.exit(0)}}]});");(root/'allow-skip').write_text('actual author admission');v=finish(root,proc,writer,1);assert(root/'accepted-skip').exists();assert v['attempts'][0]['status']=='failed'and not v['attempts'][0]['expected']and not v['attachments']and not files(root)and v['workers'][0]['exitCode']==0 and v['workers'][0]['signal']is None
